El vendedor indica una biblioteca incorrecta, da error. Añade la biblioteca Adafruit_SSD1306 y funcionará correctamente. Adjunto un código para imprimir por pantalla " Hola! ". El terminal SDA al pin A4, el SCL al pin A5, VCC a 3,5 o 5v y GRD a tierra. Copia y pega lo siguiente, espero que os ayude:

#define SCREEN_WIDTH 128 // Ancho de la pantalla
#define SCREEN_HEIGHT 64 // Alto de la pantalla

// Crear el objeto para la pantalla OLED
Adafruit_SSD1306 display(SCREEN_WIDTH, SCREEN_HEIGHT, &Wire, -1); // Usar -1 si no se utiliza el pin de reset

void setup() {
// Inicializa la pantalla OLED con la dirección I2C 0x3C
if (!display.begin(SSD1306_SWITCHCAPVCC, 0x3C)) {
Serial.println(F("Error al inicializar OLED"));
for(;;); // Detener si no se puede inicializar
}

// Limpiar el buffer de la pantalla
display.clearDisplay();

// Establecer el tamaño de la fuente
display.setTextSize(3); // Tamaño de texto (1 es más pequeño, 2 más grande)
display.setTextColor(WHITE); // Color del texto (blanco)

// Colocar el cursor en la posición deseada
display.setCursor(0, 0); // Colocar en la fila 0, columna 0
display.print("Hola"); // Escribir "Hola" en la pantalla

// Actualiza la pantalla para mostrar el contenido
display.display();
}

void loop() {
// No se necesita hacer nada aquí
}

